head.script:
scwin.trigger1_onclick = function(e) {
    document.body.style.transform = "scale(1)";
};
scwin.trigger2_onclick = function(e) {
    document.body.style.transform = "scale(0.75)";
};

scwin.simulateWrapper = function(target, type, options) {
	WebSquare.wUnit.getJq(target).simulate(type, options);
}
scwin.setSimulate = function() {
	scwin.simulateWrapper('#gridView1_cell_0_0', 'drag-n-drop', {
		dx: 0,
		dy: 30
	});
}
scwin.checkVal1 = function() {
    return typeof gridView1_drag != "";
};
scwin.unitTest = function() {
    //init
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger2').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "scwin.setSimulate()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal1()", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.unitTest();

scwin.onpageload = function() {
    gridView1.bind("onmousedown", function(e) {
        window.it = this.event.getTargetIterator(e);
        while (it.next()) {
            if (it.match(null, null, "td")) {
                window.tdElem = it.getElement();
                window.value = [];
                window.rowIndex = this.rowIndex + parseInt(parseInt(tdElem.getAttribute("tdIndex")) / (this.oneRowDataLength + this.defaultColCnt));
                window.colId = tdElem.getAttribute("col_id");
                gridView1.setFocusedCell(rowIndex, colId, false);
                value.push(colId);
                window.displayValue = [];
                for (var i = 0; i < value.length; i++) {
                    displayValue.push(this.getCellDisplayData(rowIndex, value[i].wq_trim()));
                }
                displayValue = displayValue.join(",");
                window._this = this;
                WebSquare.dragdrop.gDragManager.activate(e, tdElem, {
                    id: this.id + "_drag",
                    component: _this,
                    contents: displayValue,
                    className: "w2grid_drag",
                    delay: 15,
                    applyMousePosition: true,
                    onDrop: function(drag, drop, x, y, dx, dy, e) {
                        window.targetTrigger = null;
                        window.targetGrid = null;
                        window.it2 = null;
                        it2 = _this.event.getTargetIterator(e);
                        //alert(it2.element.tagName);
                    }
                });
                return;
            }
        }
    });
    //Function 
    //Created by: Thuyet.Pham
    //Created date: 05-May-2018
}
